export function trackOf(topic: string): TrackId {
  if (topic === 'lang' || topic.startsWith('lang')) return 'prog_langs';
  if (topic === 'blocks') return 'blocks';
  if (topic === 'software') return 'software';
  if (topic === 'graphics') return 'graphics';
  if (topic === 'web-care') return 'web_care';
  if (topic === 'ai') return 'ai_science';
  if (topic === 'security') return 'security';
  if (topic === 'hack') return 'ethical_hacking';
  if (topic === 'threat') return 'threat_analysis';
  if (topic === 'quantum') return 'quantum';
  if (topic.startsWith('tool-')) return 'ai_tools';
  if (topic === 'proj') return 'ai_projects';
  if (topic === 'it') return 'it_sciences';
  if (topic === 'fr') return 'frontier';
  if (topic === 'ch') return 'chemistry';
  if (topic === 'ph') return 'physics';
  if (topic === 'ma') return 'math';
  if (topic === 'com') return 'commerce';
  if (topic === 'law') return 'law';
  if (topic === 'pr') return 'pr';
  if (topic === 'mg') return 'management';
  if (topic === 'hi') return 'history';
  if (topic === 'ge') return 'geography';
  if (topic === 'lit') return 'literature';
  if (topic === 'soc') return 'social';
  if (topic === 'ps') return 'psychology';
  if (topic === 'cps') return 'cyber_psych';
  if (topic === 'ux') return 'ux_psych';
  if (topic === 'bio') return 'biology';
  if (topic === 'med') return 'medicine';
  if (topic === 'eng') return 'engineering';
  if (topic === 'earth') return 'earth_space';
  if (topic === 'edu') return 'education';
  if (topic === 'media') return 'media_info';
  if (topic === 'sport') return 'sports';
  if (topic === 'art') return 'arts';
  if (topic === 'rel') return 'religion';
  if (topic === 'tour') return 'tourism_ir';
  if (topic === 'academic') return 'academic';
  if (topic === 'vocational') return 'vocational';
  if (topic === 'technical') return 'technical';
  if (topic === 'experimental') return 'experimental';
  if (topic === 'smart_agents') return 'smart_agents';
  if (topic.startsWith('expert:')) {
    const expertTracks: Record<string, TrackId> = {
      'human-medicine': 'medicine', veterinary: 'medicine', biosafety: 'medicine', nutrition: 'medicine',
      space: 'earth_space', earth: 'earth_space', chemistry: 'chemistry', physics: 'physics', nuclear: 'physics',
      math: 'math', biology: 'biology', agriculture: 'biology', semiconductors: 'engineering',
      'electronic-warfare': 'engineering', computing: 'it_sciences', 'war-studies': 'history', logic: 'religion',
    };
    return expertTracks[topic.slice('expert:'.length)] ?? 'perfume';
  }
  return 'perfume';
}

