// ── Shared lesson builders ───────────────────────────────────────────────────────────────────────────────
export interface AcademyLesson extends TrainingDoc { track: TrackId; topic: string }
export interface AcademyPair { lesson: AcademyLesson; question: BankQuestion }

const lang = (ar: string, en: string, family: keyof typeof LANGUAGE_FAMILIES, useAr: string): AcademyLesson => ({
  id: `lang-${ar}`,
  title: `لغة ${ar}`,
  content: `«${ar}» (${en}) — ${LANGUAGE_FAMILIES[family]}. ${useAr}`,
  tags: ['لغات البرمجة', LANGUAGE_FAMILIES[family]],
  track: 'prog_langs', topic: 'lang',
});

export const lesson = (id: string, track: TrackId, topic: string, title: string, content: string): AcademyLesson => ({
  id, title, content, tags: [TRACKS.find((t) => t.id === track)!.titleAr], track, topic,
});

export const ask = (l: AcademyLesson, q: string, topic = l.topic, track = l.track): AcademyPair => ({
  lesson: l,
  question: { q, lang: 'ar', topic, origin: 'curriculum' },
});

