function toolPairs(): AcademyPair[] {
  return AI_TOOLS.flatMap((tool) => {
    const t = TOOL_FIELDS[tool.id];
    const about = lesson(`tool-${tool.id}-about`, 'ai_tools', `tool-${tool.id}`, `مجال ${t.field}`, t.aboutAr);
    const develop = lesson(`tool-${tool.id}-dev`, 'ai_tools', `tool-${tool.id}`, `طرق تطوير ${t.field}`, t.developAr);
    return [
      ask(about, `ايه مجال ${t.field} في المنصة؟`, `tool-${tool.id}`, 'ai_tools'),
      ask(develop, `ايه هي طرق تطوير ${t.field}؟`, `tool-${tool.id}`, 'ai_tools'),
    ];
  });
}

